 */
ekspor fungsi async kalimat pencarian(
  pertanyaan:string,
  filter: SearchFilterOptions = {}
): Janji<{ hasil: SentenceItem[]; jumlah:jumlah; SemanticMatches?: SemanticExplanationMatch[] }> {
  const all = menunggu loadSentences();
  const normalizedQuery = normalizeText(kueri);
  const queryTokens = normalizedQuery? normalizedQuery.split(' ').filter(Boolean) : [];

  konstanta {
    cefr = 'semua',
    bagian = 'semua',
    kategori = 'semua',
    subkategori = 'semua',
    tata bahasa = 'semua',
    formalitas = 'semua',
    batas = 50,
    offset = 0,
  } = filter;

  // Filter lolos
  biarkan difilter = semua.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) menghasilkan false;
    if (bagian !== 'semua' && s.bagian !==bagian) menghasilkan false;
    if (kategori !== 'semua' && s.kategori !== kategori) menghasilkan false;
    if (subkategori !== 'semua' && s.subkategori !== subkategori) menghasilkan false;
    if (tata bahasa !== 'semua' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) mengembalikan false;
    if (formalitas !== 'semua' && s.formality.toLowerCase() !== formality.toLowerCase()) mengembalikan false;
    kembali benar;
  });

  jika (!normalizedQuery) {
    const total = difilter.panjang;
    const diberi nomor halaman = difilter. irisan(offset, offset + batas);
    return { hasil: diberi nomor halaman, total };
  }

  // Algoritma penilaian
  antarmukaScoredItem {
    barang:Item Kalimat;
    skor:angka;
    aspek: SemanticExplanationMatch['matchedAspect'];
  }

  skor konstan: ScoredItem[] = [];

  for (const s yang difilter) {
    misalkan skor = 0;
    biarkan matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'bahasa inggris';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizeText(s.tujuan);

    // Pencocokan kalimat lengkap yang tepat
    jika (normEn === Kueri yang dinormalisasi) {
      skor += 100;
      matchedAspect = 'bahasa inggris';
    } else if (normEg === Kueri yang dinormalisasi) {
      skor += 95;
      matchedAspect = 'misalnya arab';
    } else if (normFusha === normalizedQuery) {
      skor += 90;
      matchedAspect = 'arab-fusha';
    }

    //Substring berisi
    if (normEn.includes(normalizedQuery)) {
      skor += 50;
      matchedAspect = 'bahasa inggris';
    } else if (normEg.includes(normalizedQuery)) {
      skor += 45;
      matchedAspect = 'misalnya arab';
    } else if (normFusha.includes(normalizedQuery)) {
      skor += 40;
      matchedAspect = 'arab-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      skor += 35;
      matchedAspect = 'tata bahasa';
    } else if (normPurpose.includes(normalizedQuery)) {
      skor += 30;
      matchedAspect = 'konsep';
    }

    // Kecocokan token
    biarkan tokenMatches = 0;
    untuk (token konstan dari queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    skor += tokenMatches;

    jika (skor > 0) {
      skor.push({ item: s, skor, aspek: matchedAspect });
    }
  }

  skor.sort((a, b) => b.skor - a.skor);

  // Penjelasan semantik cocok untuk item teratas
