      nuance = 'Present perfect continuous tense menekankan waktu dari masa lalu dan berlanjut hingga saat berbicara.';
    } else if (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuance = 'Future Perfect Tense menyatakan bahwa suatu peristiwa akan selesai sebelum waktu tertentu di masa depan.';
