/**
 * Kalimat Harian deterministik (Identik untuk semua pengguna pada hari tertentu)
 */
ekspor fungsi async getDailySentence(): Janji<SentenceItem | batal> {
  const all = menunggu loadSentences();
  if (all.length === 0) return null;

  const hari ini = Tanggal baru();
  const dayOfYear = Matematika.lantai(
    (hari ini.getTime() - Tanggal baru(hari ini.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24
  );
  const indeks = Math.abs((dayOfYear * 97 + hari ini.getFullYear()) % all.length);
  kembalikan semua[indeks] || semua[0];
}

